import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static void bitAdd(long[] t, int i, long x) {
        int n = t.length - 1;
        for (; i <= n; i += i & -i) t[i] += x;
    }

    static long bitSum(long[] t, int i) {
        long s = 0;
        for (; i > 0; i -= i & -i) s += t[i];
        return s;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[] w = new long[(int) n];
        for (int i = 0; i < w.length; i++) w[i] = Long.parseLong(next());
        long[][] ops = new long[(int) q][3];
        for (int i = 0; i < ops.length; i++) {
            for (int j = 0; j < ops[i].length; j++) {
                ops[i][j] = Long.parseLong(next());
            }
        }

        int m = (int) n;
        long[] t = new long[m + 1];
        long[] cur = new long[m + 1];
        long total = 0;
        for (int i = 1; i <= m; i++) {
            cur[i] = w[i - 1];
            bitAdd(t, i, cur[i]);
            total += cur[i];
        }
        int top = 1;
        while (top * 2 <= m) top *= 2;
        StringBuilder out = new StringBuilder();
        for (int j = 0; j < q; j++) {
            long kind = ops[j][0];
            int x = (int) ops[j][1];
            long y = ops[j][2];
            if (kind == 1) {
                bitAdd(t, x, y - cur[x]);
                total += y - cur[x];
                cur[x] = y;
            } else {
                long k = (total + 1) / 2;
                int pos = 0;
                for (int step = top; step > 0; step >>= 1) {
                    if (pos + step <= m && t[pos + step] < k) {
                        pos += step;
                        k -= t[pos];
                    }
                }
                if (out.length() > 0) out.append(" ");
                out.append(pos + 1);
            }
        }
        System.out.println(out);
    }
}
